class JournalScreen extends StatelessWidget { const JournalScreen({super.key}); Future<void> _add(BuildContext context) async { final c=TextEditingController(); final r=await showDialog<String>(context:context,builder:(x)=>AlertDialog(title:const Text('سجّلي موقفًا',style:TextStyle(fontWeight:FontWeight.w900)),content:TextField(controller:c,maxLines:5,autofocus:true,decoration:const InputDecoration(hintText:'شو صار؟ شو حسّيتي؟ شو عملتي؟')),actions:[TextButton(onPressed:()=>Navigator.pop(x),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(x,c.text.trim()),child:const Text('حفظ'))])); c.dispose(); if(r!=null&&r.isNotEmpty) await AppScope.of(context).addJournal(r); }
